def methods(paths):
    found=[]
    for p in paths:
        if p in coverage:
            found += [f"{Path(p).stem}::{m['name']} ({p}:{m['line']})" for m in coverage[p]['methods'] if m['visibility']=='public' and m['name']!='__construct']
    return found

def dbops(tables,n):
    if not tables:return 'No persistent database operation in this capability; browser/session/file state may apply as described.'
    action=('SELECT for display/aggregation' if n in [23,24,31,32,33,34,35,36,39,40,43,44,45,46,48] else 'Read and/or write through the cited service; exact method and constraints are recorded in the backend audit')
    return action+': '+', '.join(tables)+'.'

