lines=['# Complete feature inventory',f'{len(features)} distinct capabilities. Repeated UI/service observations are merged; related sub-actions remain within a capability. This count does not equate to completed end-to-end verification.','| Classification | Count |','|---|---:|']+[f'| {s} | {counts[s]} |' for s in all_status]
lines+=['Verified working is limited to the exact capability boundary: mobile menu, tested result theme toggle, clipboard copy, text export, and static health. Partial means an implemented capability has a demonstrated or source-confirmed limitation; it does not mean every operation fails. Other implemented facilities remain unverified end-to-end. No missing feature is inferred from an unapproved wish list.','## Source method anchors','Functions below are public methods in the associated classes, supplied for navigation. They are not a claim that every listed method runs on every action. Complete method/line inventories are in evidence/backend-feature-notes.json; Python definitions are in evidence/python-source-map.json.']
for f in features:
    lines += [f"## {f['id']}. {f['name']}",f"**Module / role / route:** {f['module']} / {f['roles']} / {f['route']}",f"**Plain-language explanation and purpose:** {f['explanation']}",f"**Need addressed:** {f['problem']}",'**User or operator steps:** '+ ' → '.join(f['steps'])+'.',f"**Inputs:** {f['inputs']}",f"**System behavior:** {f['behavior']}",f"**Expected output:** {f['outputs']}",f"**Related workflows:** {f['related']}",'**Frontend:** '+('; '.join(f['frontend']) or 'No dedicated interface; internal/API/CLI capability.'),'**Backend:** '+('; '.join(f['backend']) or 'No backend for the named browser-only action.'),'**Controller/service anchors:** '+('; '.join(f['functions']) or 'See script/definition map for the cited entry points.'),f"**Database operations:** {f['database_operations']}",f"**External dependencies:** {f['dependencies']}",f"**Implementation / classification:** {f['implemented']} / {f['status']}",f"**Testing:** {f['tested']}",f"**Observed result:** {f['observed']}",f"**Limitations:** {f['limitations']}",'**Evidence:** '+'; '.join(f['evidence'])]
write(AUD/'FEATURE_INVENTORY.md','\n\n'.join(lines))

# Standalone chapter section, included in Chapter III to keep every capability visible.
feature_prose=['## 3. Essential Features and Functionalities','The following inventory describes each distinct capability in language intended for readers who are not software developers. Each identifier corresponds to the full evidence, file, function, input and database record in FEATURE_INVENTORY.csv. “Implemented but not verified” means implementation was inspected without completing its operational workflow. “Partially working” identifies an implemented facility with a supported limitation. “Verified working” applies only to the narrow action expressly tested. Benefits describe intended use rather than measured learning or productivity gains.']
last=None
for f in features:
    if f['module']!=last:
        feature_prose.append('### '+f['module']);last=f['module']
    purpose=f['explanation']
    if purpose.startswith('As '):
        purpose='The feature allows '+f['roles']+' to '+f['purpose']+'.'
    feature_prose += [f"**{f['id']}. {f['name']}.** {purpose} The intended output is {f['outputs'].rstrip('.')}. It connects with {f['related'].lower()}.", 'The interaction proceeds as follows: '+'; then '.join(s.rstrip('.').lower() for s in f['steps'])+'. Inputs are '+f['inputs'].rstrip('.')+'. Behind the interface, the implementation performs '+f['behavior'].rstrip('.')+'.',f"The audit classification is {f['status'].lower()}. {f['limitations']} Evidence is recorded under {f['id']} in the feature inventory; a template capture or function test does not verify the full saved workflow."]
write(MAN/'tables/FEATURE_DISCUSSION.md','\n\n'.join(feature_prose))

# Correct the initial smoke-test interpretation without altering raw logs.
for name in ['FUNCTIONAL_TEST_RESULTS.md','PYTHON_ENGINE_AUDIT.md']:
    p=AUD/name;s=read(p)
    s=s.replace('A direct synthetic Python call returned output, but the database/web save path was not tested.','The direct synthetic Python call returned status insufficient_content and an empty nutshell. Its harness PASS label records a returned response, not successful generation; the database/web save path was not tested.')
    s=s.replace('direct Q&A and Nutshell calls also returned results.','direct Q&A returned a source passage. The Nutshell call returned an empty insufficient-content response, so successful Nutshell generation was not established.')
    s=s.replace('| Nutshell function | Call concise-summary function on synthetic text; expect output | Output returned | PASS at Python-function scope; isolated-smoke-results.json |','| Nutshell function | Call concise-summary function on synthetic text; inspect response | insufficient_content; empty nutshell; raw harness PASS means response returned only | GENERATION NOT DEMONSTRATED; isolated-smoke-results.json |')
    s=s.replace('Render19states at1440desktop and390mobile widths |38captures','Render23states at1440desktop and390mobile widths |46captures').replace('10of10baseline assertions matched','18of18 local assertions matched (baseline plus supplements)').replace('19guard observations recorded','19of19 guard responses matched their source-based expectations')
    write(p,s)
print(json.dumps({'count':len(features),'breakdown':dict(counts)}))
